	if(!CanExecute())
	{
		return;
	}

	DECLARE_SCOPE_HIERARCHICAL_COUNTER_FUNC()

	ControlRigHierarchyMappings.UpdateInput(ControlRig
		, InOutput
		, InputSettings
		, OutputSettings
		, NodeMappingContainer
		, bExecute
		, bTransferInputPose
		, bResetInputPoseToInitial
